const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const prices = data.slice(1).sort((a, b) => b - a);

let total = 0;
for (let i = 0; i < n; i++) {
  if (i % 3 !== 2) total += prices[i];
}

console.log(total);
